 verify_csrf();$methodId=(int)$_POST['method_id'];$q=db()->prepare('SELECT * FROM donation_methods WHERE id=? AND active=1');$q->execute([$methodId]);$method=$q->fetch();if(!$method)throw new RuntimeException('Método no disponible.');$amount=max(0,(int)preg_replace('/\D+/','',(string)$_POST['amount_clp']));if($amount<=0)throw new RuntimeException('Ingresa el equivalente en pesos chilenos.');
 $proof=upload_donation_proof();if(!$proof)throw new RuntimeException('Debes adjuntar un comprobante.');$donatedAt=str_replace('T',' ',trim((string)$_POST['donated_at']));if(!$donatedAt||strtotime($donatedAt)===false)$donatedAt=date('Y-m-d H:i:s');
